package quebec.culture.donnees;

import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;

public class IndigenousActivity extends Activity{
 private static final int BLUE=Color.rgb(0,59,113),TEXT=Color.rgb(28,45,62),GREEN=Color.rgb(18,104,72);private final Handler ui=new Handler(Looper.getMainLooper());private IndigenousDatabase db;private LinearLayout dynamic;private TextView status;private EditText query;private Spinner nationFilter;
 @Override protected void onCreate(Bundle b){super.onCreate(b);db=new IndigenousDatabase(this);getWindow().setStatusBarColor(Color.rgb(0,40,77));getWindow().setNavigationBarColor(Color.rgb(0,40,77));setContentView(build());}
 private View build(){ScrollView sv=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(18),dp(18),dp(36));root.setBackgroundColor(Color.rgb(245,247,250));sv.addView(root);applyInsets(root);Button back=secondary("← Retour");back.setOnClickListener(v->finish());root.addView(back);root.addView(text("Vitrine des 11 nations",29,BLUE,true));root.addView(text("Espace culturel autochtone du Québec · histoire, nations, langues, communautés et données en direct",14,TEXT,false),mb());
  LinearLayout intro=panel();intro.addView(text("Une section dédiée",21,TEXT,true));intro.addView(text("Cette section regroupe les 10 Premières Nations et la nation inuit reconnues au Québec. Chaque nation possède une identité, une langue, une histoire et une culture qui lui sont propres. La base locale est enrichie par des recherches dans les données publiques et par le moteur culturel de l’application.",15,TEXT,false));intro.addView(text("Objectif : réserver un espace clair et durable aux contenus autochtones dans Culture du Québec, sans les mélanger à une catégorie générique.",13,GREEN,true));root.addView(intro,mb());
  root.addView(text("Les 11 nations",22,TEXT,true),mb());for(IndigenousDatabase.Nation n:db.nations()){Button b=secondary("◈  "+n.name+"  ›");b.setOnClickListener(v->showNation(n));root.addView(b);}root.addView(space(12));
  LinearLayout timeline=panel();timeline.addView(text("Histoire · 1534 à aujourd’hui",22,TEXT,true));timeline.addView(text("Chronologie de départ fondée sur des sources gouvernementales, juridiques, archivistiques et autochtones. Elle n’est pas présentée comme exhaustive : la recherche en direct sert à l’enrichir.",13,Color.DKGRAY,false));for(IndigenousDatabase.History h:db.history())timeline.addView(historyCard(h));root.addView(timeline,mb());
  LinearLayout live=panel();live.addView(text("Base de données autochtone en direct",22,TEXT,true));live.addView(text("Recherchez un mot, une nation, une communauté, un organisme, une œuvre, un programme ou un événement. Les résultats récupérés de Données Québec sont conservés dans la base locale afin de pouvoir les retrouver ensuite.",14,TEXT,false));query=new EditText(this);query.setHint("Ex. Atikamekw, Wendake, Inuit, patrimoine, langue…");query.setSingleLine(true);live.addView(query,new LinearLayout.LayoutParams(-1,dp(56)));List<String> names=new ArrayList<>();names.add("Toutes les nations");for(IndigenousDatabase.Nation n:db.nations())names.add(n.name);nationFilter=new Spinner(this);nationFilter.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));live.addView(nationFilter,new LinearLayout.LayoutParams(-1,dp(54)));Button sync=primary("↻ Rechercher dans les données officielles");sync.setOnClickListener(v->syncOfficial());live.addView(sync);Button local=secondary("Afficher la base locale");local.setOnClickListener(v->showLocal());live.addView(local);Button web=secondary("🔎 Rechercher sur le Web culturel québécois");web.setOnClickListener(v->openFederated());live.addView(web);root.addView(live,mb());status=text("La base est prête.",14,Color.DKGRAY,false);root.addView(status,mb());dynamic=new LinearLayout(this);dynamic.setOrientation(LinearLayout.VERTICAL);root.addView(dynamic);
  LinearLayout sources=panel();sources.addView(text("Sources de référence intégrées",20,TEXT,true));sources.addView(text("Profils officiels des 11 nations · Secrétariat aux relations avec les Premières Nations et les Inuit · Données Québec · textes juridiques et ententes · Commission Viens · Centre national pour la vérité et la réconciliation. Les pages de chaque nation donnent accès à leur profil officiel et la recherche Web peut trouver des organismes et médias autochtones.",13,TEXT,false));Button official=secondary("Ouvrir le portail Premières Nations et Inuit du Québec");official.setOnClickListener(v->open("https://www.quebec.ca/gouvernement/portrait-quebec/premieres-nations-inuits"));sources.addView(official);root.addView(sources);return sv;}
 private void showNation(IndigenousDatabase.Nation n){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(8),dp(8),dp(8),dp(8));p.addView(text(n.selfName,20,BLUE,true));p.addView(text("Langue : "+n.language+"\nCommunautés : "+n.communities+"\nTerritoire : "+n.territory+"\n\n"+n.summary,14,TEXT,false));new AlertDialog.Builder(this).setTitle(n.name).setView(p).setPositiveButton("Profil officiel",(d,w)->open(n.profileUrl)).setNeutralButton("Rechercher",(d,w)->{Intent i=new Intent(this,SearchActivity.class);i.putExtra("prefill",n.name+" autochtone Québec");i.putExtra("auto_search",true);startActivity(i);}).setNegativeButton("Fermer",null).show();}
 private View historyCard(IndigenousDatabase.History h){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(0,dp(12),0,dp(12));TextView y=text(String.valueOf(h.year)+" · "+h.label,16,BLUE,true);c.addView(y);c.addView(text(h.details,13,TEXT,false));c.addView(text("Nations : "+h.nations,12,Color.DKGRAY,false));Button src=linkButton("Source / repère historique");src.setOnClickListener(v->open(h.sourceUrl));c.addView(src);return c;}
 private void syncOfficial(){String q=query.getText().toString().trim();String nf=String.valueOf(nationFilter.getSelectedItem());if(q.isEmpty()&&nf.equals("Toutes les nations"))q="autochtone";String finalQ=q;status.setText("Recherche dans Données Québec…");dynamic.removeAllViews();new Thread(()->{LinkedHashMap<String,JSONObject> found=new LinkedHashMap<>();try{List<String> terms=new ArrayList<>();if(!nf.equals("Toutes les nations"))terms.add(nf+" "+finalQ);else{terms.add(finalQ+" autochtone");terms.add(finalQ+" Premières Nations");terms.add(finalQ+" Inuit");}for(String term:terms){String u="https://www.donneesquebec.ca/recherche/api/3/action/package_search?q="+URLEncoder.encode(term.trim(),"UTF-8")+"&rows=50&sort=metadata_modified%20desc";JSONArray a=new JSONObject(get(u)).getJSONObject("result").optJSONArray("results");if(a==null)continue;for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p==null)continue;String name=p.optString("name");if(!name.isEmpty())found.put(name,p);}}
   for(JSONObject p:found.values()){String title=p.optString("title",p.optString("name"));String url="https://www.donneesquebec.ca/recherche/dataset/"+p.optString("name");String date=p.optString("metadata_modified","");String summary=strip(p.optString("notes",""));String source="Données Québec";try{source=p.getJSONObject("organization").optString("title",source);}catch(Exception ignored){}db.upsertSource(title,url,source,date,nf,summary);}ui.post(()->{status.setText(found.size()+" jeu(x) de données ajouté(s)/mis à jour dans la base autochtone.");showLocal();});}catch(Exception e){ui.post(()->status.setText("Recherche impossible pour le moment : "+safe(e.getMessage())));}}).start();}
 private void showLocal(){String q=query==null?"":query.getText().toString().trim();List<IndigenousDatabase.SourceRow> rows=db.searchSources(q);dynamic.removeAllViews();status.setText(rows.size()+" résultat(s) dans la base autochtone locale.");if(rows.isEmpty()){dynamic.addView(text("Aucune donnée récupérée pour ce filtre. Lancez d’abord une recherche officielle ou utilisez le moteur Web.",14,Color.DKGRAY,false));return;}for(IndigenousDatabase.SourceRow r:rows){LinearLayout c=panel();c.addView(text(r.title,17,TEXT,true));c.addView(text("OFFICIEL · "+r.source,12,GREEN,true));if(r.date!=null&&!r.date.isEmpty())c.addView(text("📅 "+friendlyDate(r.date),12,TEXT,false));if(r.summary!=null&&!r.summary.isEmpty())c.addView(text(shorten(r.summary,260),13,Color.DKGRAY,false));Button b=primarySmall("OUVRIR LA SOURCE");b.setOnClickListener(v->open(r.url));c.addView(b);dynamic.addView(c,mb());}}
 private void openFederated(){String q=query.getText().toString().trim();String nf=String.valueOf(nationFilter.getSelectedItem());String terms=(nf.equals("Toutes les nations")?"autochtone Premières Nations Inuit Québec":nf+" Québec")+(q.isEmpty()?"":" "+q);Intent i=new Intent(this,SearchActivity.class);i.putExtra("prefill",terms);i.putExtra("auto_search",true);startActivity(i);}
 private String get(String address)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(18000);c.setRequestProperty("Accept","application/json");c.setRequestProperty("User-Agent","CultureDuQuebec/1.7");BufferedReader b=new BufferedReader(new InputStreamReader(c.getInputStream(),StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();String l;while((l=b.readLine())!=null)s.append(l);b.close();c.disconnect();return s.toString();}
 private void open(String u){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception ignored){}}private String strip(String s){return s==null?"":s.replaceAll("<[^>]*>"," ").replace("&nbsp;"," ").replaceAll("\\s+"," ").trim();}private String shorten(String s,int n){return s.length()<=n?s:s.substring(0,n-1)+"…";}private String friendlyDate(String s){if(s.length()>=10&&s.charAt(4)=='-'&&s.charAt(7)=='-')return s.substring(8,10)+"/"+s.substring(5,7)+"/"+s.substring(0,4);return s;}private String safe(String s){return s==null?"erreur réseau":s;}
 private void applyInsets(View v){v.setOnApplyWindowInsetsListener((view,in)->{android.graphics.Insets b=in.getInsets(WindowInsets.Type.systemBars());view.setPadding(dp(18),dp(18)+b.top,dp(18),dp(36)+b.bottom);return in;});v.requestApplyInsets();}private LinearLayout panel(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(16),dp(16),dp(16),dp(16));p.setBackgroundResource(R.drawable.panel);return p;}private TextView text(String s,int sp,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(c);if(bold)t.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);t.setLineSpacing(0,1.12f);return t;}private Button primary(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setBackgroundResource(R.drawable.button_primary);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(9);b.setLayoutParams(lp);return b;}private Button secondary(String s){Button b=new Button(this);b.setText(s);b.setTextColor(BLUE);b.setAllCaps(false);b.setBackgroundResource(R.drawable.button_secondary);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(8);b.setLayoutParams(lp);return b;}private Button primarySmall(String s){Button b=primary(s);b.setTextSize(12);return b;}private Button linkButton(String s){Button b=new Button(this);b.setText(s);b.setTextColor(BLUE);b.setAllCaps(false);b.setBackgroundColor(Color.TRANSPARENT);b.setGravity(Gravity.START);return b;}private View space(int h){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(1,dp(h)));return s;}private LinearLayout.LayoutParams mb(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(14);return p;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}}
